    for (let i = 0; i < 5; i++) {
      particles.push({
        x: obs.x + size / 2 + (Math.random() - 0.5) * 10,
        y: obs.y - size / 2 + (Math.random() - 0.5) * 10,
        vy: - (1 + Math.random() * 1),
        alpha: 1,
        size: 2 + Math.random() * 2,
        color: '#0ff'
      });
    }
  }

